// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public {
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function testFuzz_property(address guesser) public {
        // keep the guesser admissible but wide: any non-zero EOA address
        vm.assume(guesser != address(0));
        vm.assume(guesser.code.length == 0);

        // The correct answer for the block that will be stored by lockInGuess is
        // keccak256(abi.encodePacked(blockhash(block.number + 1))).
        bytes32 answer = keccak256(abi.encodePacked(blockhash(block.number + 1)));

        vm.deal(guesser, 1 ether);
        vm.prank(guesser);
        c.lockInGuess{value: 1 ether}(answer);

        // advance so that settle's block-number guard passes
        vm.roll(block.number + 2);

        vm.prank(guesser);
        c.settle();

        uint256 balanceAfterFirst = guesser.balance;

        // attempt a second settle with the same guess
        bool secondSettleSucceeded;
        vm.prank(guesser);
        try c.settle() {
            secondSettleSucceeded = true;
        } catch {
            secondSettleSucceeded = false;
        }

        // Reference: first settle paid 2 ether and cleared the guess block, so the
        // second settle must revert and the balance must stay at the after-first value.
        // Mutant: second settle succeeds and pays another 2 ether, so the balance grows.
        assertTrue(secondSettleSucceeded == false && guesser.balance == balanceAfterFirst);
    }
}
